#!/usr/bin/env python3
"""Fail a commit when the index contains generated Goose C above a size limit.

The marker is the compiler's own header, not the file name:

    /* Generated by the Goose compiler from <source>. Do not edit.
    ...
    /* ==== runtime.h ==== */

Usage:
    python3 tools/check-generated-files.py            # index vs HEAD
    python3 tools/check-generated-files.py --all      # flag any generated C
    python3 tools/check-generated-files.py --mb 1     # size limit (default 1)

Intended as a pre-commit hook (see tools/README or the report). Hand-written C
is never matched, even when it is large. A generated file below the limit is
printed as a warning; a generated file at or above it fails the run.

The policy decisions — what counts as a generated artifact, the limit in bytes
and the fail/warn verdict — are the P10-05 S3 slice, `goose/misc/
generated-artifact-policy.goose`, reached through `build/goose-hosts/art`
(`bash tools/goose-hosts/build.sh`). This script keeps the git index access,
the head truncation and the messages. `BMOE_GOOSE_ART=0` restores the inline
policy, and so does a missing host binary, with a notice on stderr.
"""

from __future__ import annotations

import argparse
import os
import subprocess
import sys
from pathlib import Path

MARKER_SOURCE = b"/* Generated by the Goose compiler from "
MARKER_DO_NOT_EDIT = b"Do not edit."
MARKER_RUNTIME = b"/* ==== runtime.h ==== */"

HOSTS_DIR = Path(__file__).resolve().parent.parent / "build" / "goose-hosts"
HOST_OPT_OUT = "BMOE_GOOSE_ART"


def git(*args: str, text: bool = True):
    return subprocess.run(["git", *args], stdout=subprocess.PIPE,
                          stderr=subprocess.PIPE, text=text, check=False)


def staged_files() -> list[str]:
    out = git("diff", "--cached", "--name-only", "--diff-filter=ACMR", "-z")
    if out.returncode != 0:
        print(f"check-generated-files: git diff failed: {out.stderr.strip()}", file=sys.stderr)
        raise SystemExit(2)
    return [p for p in out.stdout.split("\0") if p]


def index_size(path: str) -> int:
    out = git("cat-file", "-s", f":{path}")
    if out.returncode != 0:
        return -1
    try:
        return int(out.stdout.strip())
    except ValueError:
        return -1


def index_head(path: str, limit: int = 512) -> bytes:
    out = git("show", f":{path}", text=False)
    if out.returncode != 0:
        return b""
    return out.stdout[:limit]


# --- the policy, as selected by the caller ---------------------------------

def _hex(data: bytes) -> str:
    return data.hex() if data else "-"


class Host:
    """One line-protocol subprocess for the whole run.

    One process per hook invocation, not one per file: the protocol is a request
    and a reply per line, so a thousand staged files are a thousand lines.
    """

    def __init__(self, path: Path):
        self.proc = subprocess.Popen([str(path)], stdin=subprocess.PIPE,
                                     stdout=subprocess.PIPE, text=True, bufsize=1)

    def ask(self, line: str) -> str:
        assert self.proc.stdin is not None and self.proc.stdout is not None
        self.proc.stdin.write(line + "\n")
        self.proc.stdin.flush()
        reply = self.proc.stdout.readline().strip()
        if not reply.startswith("OK "):
            raise RuntimeError(f"goose host art: {reply or 'no reply'}")
        return reply[3:]

    def close(self) -> None:
        if self.proc.stdin is not None:
            self.proc.stdin.close()
        self.proc.wait(timeout=30)


def open_host() -> Host | None:
    if os.environ.get(HOST_OPT_OUT, "1") == "0":
        return None
    binary = HOSTS_DIR / "art"
    if not binary.is_file():
        print(f"check-generated-files: {binary} is missing, using the inline policy "
              f"(build it with: bash tools/goose-hosts/build.sh)", file=sys.stderr)
        return None
    return Host(binary)


def is_generated_goose_c(path: str, head: bytes, host: Host | None = None) -> bool:
    if host is not None:
        return host.ask(f"GEN {_hex(path.encode())} {_hex(head)}") == "1"
    # Generated Goose C comes in two shapes: --standalone embeds runtime.h,
    # --emit-runtime leaves it out. The first-line banner is common to both.
    if path.endswith(".c"):
        return head.startswith(MARKER_SOURCE) and MARKER_DO_NOT_EDIT in head
    # CUDA headers written by the experiment's generator scripts, either
    # named "*-generated.cuh" or placed under a generated/ directory.
    if path.endswith(".cuh") and "generated" in path.lower():
        return True
    return False


def size_limit(mb: float, host: Host | None = None) -> int:
    if host is not None:
        # The slice takes integer milli-MiB, so the caller rounds the CLI value.
        return int(host.ask(f"LIM {int(round(mb * 1000))}"))
    return int(mb * 1024 * 1024)


def gate(all_flag: bool, size: int, limit: int, host: Host | None = None) -> int:
    """2 = the commit fails, 1 = warned, 0 = not a generated artifact."""
    if host is not None:
        return int(host.ask(f"GATE {int(all_flag)} {size} {limit}"))
    if all_flag or size >= limit:
        return 2
    return 1


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--mb", type=float, default=1.0,
                    help="size limit in MiB (default 1)")
    ap.add_argument("--all", action="store_true",
                    help="fail on any generated C, regardless of size")
    args = ap.parse_args()

    host = open_host()
    try:
        limit = size_limit(args.mb, host)
        failed: list[tuple[str, int]] = []
        warned: list[tuple[str, int]] = []

        for path in staged_files():
            if not (path.endswith(".c") or path.endswith(".cuh")):
                continue
            size = index_size(path)
            if size < 0:
                continue
            head = index_head(path)
            if not is_generated_goose_c(path, head, host):
                continue
            if gate(args.all, size, limit, host) == 2:
                failed.append((path, size))
            else:
                warned.append((path, size))
    finally:
        if host is not None:
            host.close()

    for path, size in warned:
        print(f"warning: generated Goose C below the limit: {path} ({size} bytes)")

    if failed:
        print("error: generated Goose C is staged for commit:", file=sys.stderr)
        for path, size in failed:
            print(f"  {path} ({size / 1048576:.1f} MiB)", file=sys.stderr)
        print("regenerate it from the .goose source instead of committing it;\n"
              "if this experiment must keep it, raise --mb with a written reason.",
              file=sys.stderr)
        return 1

    print(f"check-generated-files: ok ({len(warned)} generated file(s) below limit)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
